{
  "families": [
    {
      "family": "pipelined_m",
      "ranges": [
        {"param": "data_width", "low": 14, "high": 20, "choices": null},
        {"param": "n_iter", "low": 14, "high": 20, "choices": null},
        {"param": "angle_guard", "low": 0, "high": 2, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 2, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
        {"param": "m", "low": 2, "high": 8, "choices": null}
      ],
      "budget_share": 0.55,
      "why": "1 result/cycle architecture; with Fmax ~200-300 MHz, throughput = Fmax x 1 easily exceeds 400 MSPS. m controls area/latency trade-off. This is the most likely feasible family for the throughput constraint."
    },
    {
      "family": "unrolled_k",
      "ranges": [
        {"param": "data_width", "low": 14, "high": 20, "choices": null},
        {"param": "n_iter", "low": 14, "high": 20, "choices": null},
        {"param": "angle_guard", "low": 0, "high": 2, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 2, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
        {"param": "k", "low": 4, "high": 8, "choices": null}
      ],
      "budget_share": 0.30,
      "why": "k micro-rotations/cycle gives throughput = Fmax x k. With k=4-8 and Fmax ~100-200 MHz, throughput can reach 400-1600 MSPS. Fewer pipeline stages than pipelined_m, potentially fewer LUTs. k>=4 needed to plausibly hit 400 MSPS at realistic Fmax."
    },
    {
      "family": "pipelined",
      "ranges": [
        {"param": "data_width", "low": 14, "high": 20, "choices": null},
        {"param": "n_iter", "low": 14, "high": 20, "choices": null},
        {"param": "angle_guard", "low": 0, "high": 2, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 2, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
      ],
      "budget_share": 0.15,
      "why": "Fully pipelined (m=1 equivalent), 1 result/cycle. Highest Fmax potential due to shortest critical path per stage, but most registers. Included to map the area/Fmax trade-off at the extreme end. Likely more LUTs+FFs than pipelined_m but may allow higher Fmax."
    }
  ],
  "rationale": "The spec requires >=400 MSPS single-lane throughput and max_abs_err <= 2^-12 (~0.000244). The iterative family (1 result per N+3 cycles) cannot plausibly reach 400 MSPS unless Fmax is extremely high (e.g., 4000+ MHz for N=14), which is unrealistic on Artix-7, so it is excluded. The three throughput-capable families are pipelined_m, unrolled_k, and pipelined. For accuracy: max_abs_err <= 2^-12 requires roughly data_width >= 14 and n_iter >= 14 (since CORDIC error ~ 2^-(n_iter+1) for the angle, and output quantization is 2^-(W-2); W=14 gives LSB=2^-12, so W>=14 is the minimum). I set data_width 14-20 and n_iter 14-20 to cover the accuracy constraint with margin while keeping LUTs low (the objective). angle_guard 0-2 and frac_guard 0-2 are small ranges since the accuracy constraint is tight at 2^-12 and large guards would waste bits without helping. m is 2-8 for pipelined_m to explore the area/latency/Fmax trade-off. k is 4-8 for unrolled_k since k<4 would need Fmax > 100 MHz x (400/k) which is tight. Budget is weighted toward pipelined_m (55%) as the most likely feasible and area-efficient family, unrolled_k (30%) as a potentially lower-area alternative, and pipelined (15%) to map the high-Fmax/low-latency corner."
}

{
  "decision": "infeasible",
  "rationale": "The throughput constraint (>= 400 MSPS) is unreachable for all families in the registry. The pipelined family, which offers the highest theoretical throughput (1 result/cycle), achieved a maximum of only 273 MSPS in Round 1. This is a 31.8% shortfall. The other families (unrolled_k, pipelined_m) have significantly lower maximum throughputs (9.7 and 171 MSPS respectively) due to their multi-cycle or reduced-register architectures, making them even further from the 400 MSPS target. Since the best-case architecture (pipelined) cannot meet the throughput requirement even with optimal parameter tuning (as evidenced by the search exploring the full range of n_iter and data_width), no design in the registry can satisfy the spec."
  ,
  "next_plan": null
}
